import json
base = "bench/results/2026-10-12/m1-ngram/replay"
off = { (r["phase"], r["id"], r["fg_bg"]): r for r in [json.loads(l) for l in open(f"{base}/off-greedy/requests.jsonl") if l.strip()] }
for lab in ["A-greedy","B-greedy"]:
    rows = [json.loads(l) for l in open(f"{base}/{lab}/requests.jsonl") if l.strip()]
    same = diff = 0; same_fg = diff_fg = 0
    by = {}
    for r in rows:
        k = (r["phase"], r["id"], r["fg_bg"])
        o = off.get(k)
        if o is None: continue
        s = o["out_sha256"] == r["out_sha256"]
        if s: same += 1
        else: diff += 1
        if r["fg_bg"] == "fg":
            if s: same_fg += 1
            else: diff_fg += 1
        by.setdefault(r["phase"], [0,0])
        by[r["phase"]][0 if s else 1] += 1
    print(f"{lab}: overall same={same} diff={diff} | fg same={same_fg} diff={diff_fg}")
    for ph in ["single-agent","single-mem","dual-agent","dual-mem"]:
        s,d = by.get(ph,[0,0]); n = s+d
        print(f"  {ph}: same {s}/{n} ({100*s/max(n,1):.0f}%) diff {d}")
# zero-draft fg mismatch examples
for lab in ["A-greedy"]:
    rows = [json.loads(l) for l in open(f"{base}/{lab}/requests.jsonl") if l.strip()]
    for r in rows:
        if r.get("draft_n",0)==0 and r["fg_bg"]=="fg":
            o = off.get((r["phase"],r["id"],"fg"))
            if o and o["out_sha256"] != r["out_sha256"]:
                print("ZERO-DRAFT fg mismatch:", lab, r["phase"], r["id"], r["predicted_n"], "sha diff:", o["out_sha256"][:8], "!=", r["out_sha256"][:8])
EOF

