import json
base = "bench/results/2026-10-12/m1-ngram/replay"
def ts(tok):
    parts = tok.split(".")
    assert len(parts) == 4, parts
    m, ss, ms, us = map(int, parts)
    return m*60 + ss + ms*1e-3 + us*1e-3*1e-3 if False else m*60 + ss + ms*1e-3 + us*1e-6
def wall(path):
    t0 = None
    for l in open(path):
        tok = l.split()[0]
        if "model loaded" in l:
            t0 = ts(tok); break
    last = None
    for l in open(path):
        last = ts(l.split()[0])
    return last - t0
def toksum(role, lab, ph):
    rows = [json.loads(l) for l in open(f"{base}/{lab}/requests.jsonl") if l.strip()]
    f = [r for r in rows if r["phase"] == ph and r["fg_bg"] == role]
    return sum(r.get("predicted_n") or 0 for r in f)
for lab in ["off-greedy","A-greedy","B-greedy"]:
    for ph in ["single-agent","single-mem","dual-agent","dual-mem"]:
        w = wall(f"{base}/{lab}/server_{ph}.log")
        fg = toksum("fg", lab, ph); bg = toksum("bg", lab, ph)
        combined = (fg+bg)/w
        print(f"{lab:12} {ph:12} wall={w:6.0f}s  fg_n={fg:6d} bg_n={bg:6d} combined={combined:6.1f} tok/s")
EOF

